import{_ as o,o as t,c as i,a0 as a}from"./chunks/framework.Bmhw_dvp.js";const g=JSON.parse('{"title":"ZViewer CLI 代理协议","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/cli-protocol.md","filePath":"advanced/cli-protocol.md","lastUpdated":1792319529000}'),s={name:"advanced/cli-protocol.md"};function d(c,e,l,n,r,p){return t(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="zviewer-cli-代理协议" tabindex="-1">ZViewer CLI 代理协议 <a class="header-anchor" href="#zviewer-cli-代理协议" aria-label="Permalink to &quot;ZViewer CLI 代理协议&quot;">​</a></h1><p><a href="https://github.com/Zero-wyc/ZViewerCLI" target="_blank" rel="noreferrer">ZViewer CLI</a> 是 Go 编写的独立仓库，通过 Socket.IO 与服务器通信，为浏览器提供两项能力：使用本机 Bilibili Cookie，以及经本机代理转发媒体流。Cookie 只保存在用户本机，不经过服务器。</p><h2 id="注册流程-v0-2-0-去房间化" tabindex="-1">注册流程（v0.2.0 去房间化） <a class="header-anchor" href="#注册流程-v0-2-0-去房间化" aria-label="Permalink to &quot;注册流程（v0.2.0 去房间化）&quot;">​</a></h2><ol><li>CLI 启动时携带 Engine.IO 握手参数 <code>{&quot;agent&quot;:&quot;zcontrol-cli&quot;}</code> 建立 WebSocket。<code>io.use</code> 中间件看到该参数直接放行并标记 <code>isCliAgent</code>，绕过通用 access_token 校验。</li><li>连接后发送 <code>cli-register</code>：</li></ol><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;proxyUrl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://127.0.0.1:9333&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;agent&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;zviewer-cli&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.2.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;user&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;用户名&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ol start="3"><li>服务端只校验必填的 <code>proxyUrl</code>，<strong>忽略任何房间号</strong>（<code>roomId</code> 仅为兼容旧版保留）。同时用 <code>normalizeLocalCliProxyUrl</code> 把 hostname <strong>强制改写为 <code>127.0.0.1</code></strong>（端口与路径不变），避免旧版 CLI 误报页面 host 导致前端 CORS 失败。</li><li>CLI 记入专用房间 <code>__cli-agents__</code>（仅为聚合查询方便，语义上等于全局注册），回 <code>cli-registered</code> 并 <code>io.emit(&#39;cli-agent-available&#39;, agentInfo)</code> 全局广播。缺少 <code>isCliAgent</code> 标记或 proxyUrl 时回 <code>cli-error</code>。</li><li>断连时全局广播 <code>cli-agent-unavailable {socketId}</code>。<code>cli-list-agents</code>（参数可省略）经 <code>io.in(&#39;__cli-agents__&#39;).fetchSockets()</code> 聚合返回。</li></ol><h2 id="作用范围与可用性" tabindex="-1">作用范围与可用性 <a class="header-anchor" href="#作用范围与可用性" aria-label="Permalink to &quot;作用范围与可用性&quot;">​</a></h2><ul><li><strong>一个 CLI 对所有房间可用</strong>：房间开关（<code>musicVideoCli</code> / <code>cliEnabled</code>）打开后自动使用，不存在「每房间各连一个 CLI」。</li><li><strong>按 user 过滤归属</strong>：<code>useCliAgent()</code> 内部按 <code>authStore</code> 中的登录用户名过滤，只保留 <code>!a.user || a.user === username</code> 的代理；不带 <code>user</code> 的旧版 CLI 视为公共代理。过滤后才写入 <code>cliAgentStore</code>，<code>getActiveCliProxyUrl</code> 直接取 <code>agents[0].proxyUrl</code>。</li><li><strong>配置只在内存</strong>：CLI 重启后 <code>serverUrl</code> 与 <code>user</code> 丢失，只有 Cookie 持久化在 <code>~/.zviewer/config.json</code>，需从网页端配置页重新带入。</li><li><strong>可用性只看是否有代理注册</strong>：<code>available = agents.length &gt; 0</code>，不强制本地健康检查通过（健康检查可能因 CORS 失败而实际服务可用）。健康检查仅在 http 本地页面每 5s 轮询 <code>/health</code>，https 页面跳过。</li></ul><h2 id="本地代理与解析" tabindex="-1">本地代理与解析 <a class="header-anchor" href="#本地代理与解析" aria-label="Permalink to &quot;本地代理与解析&quot;">​</a></h2><p>CLI 在本机启动 HTTP 服务，默认 <code>127.0.0.1:9333</code>（<code>-port</code> 可改），路由：<code>/health</code>、<code>/api/config</code>、<code>/api/qr</code>、<code>/api/qr/poll</code>、<code>/api/connect</code>、<code>/api/disconnect</code>、<code>/api/bili-info</code>、<code>/api/dash-mpd</code>、<code>/resolve</code>、<code>/proxy</code>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>浏览器 &lt;video&gt;/&lt;audio&gt;</span></span>
<span class="line"><span>   │  http://127.0.0.1:9333/proxy?url=...</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>ZViewer CLI 本地 HTTP 代理   注入本地 Cookie + Referer / Origin / User-Agent</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>Bilibili CDN（最高大会员档位）</span></span></code></pre></div><ul><li><strong>优先 DASH</strong>：已连接的高画质模式强制 <code>forceDash</code>，禁用 MP4 降级，音视频以 m4s 分离。<code>/resolve</code> 同时返回原始 CDN URL（供 <code>/api/dash-mpd</code> 生成 MPD 喂给 MSE）与重写为本地代理的 URL。</li><li><strong>主地址失败切备用 CDN</strong>：<code>/proxy</code> 请求主 URL 失败后按解析期缓存的 <code>backupUrl</code> 依次重试；透传 Range；B站 CDN 偶尔返回 <code>application/json</code> 的视频数据，纠正为 <code>video/mp4</code>；上游超时 60s，连接池 <code>MaxIdleConns=100 / PerHost=20</code>。</li><li><strong>清晰度档位</strong>：<code>qn</code> 取值 127(8K) / 126(杜比) / 125(HDR) / 120(4K) / 116 / 112 / 80 / 74 / 64 / 32 / 16。请求参数 <code>fnval = 16 | (VIP ? 128 : 0)</code>，qn=127 时追加 8K 标志位；会员档白名单 <code>[112,116,120,125,126,127]</code>。MP4 直链最高 1080P（<code>mp4MaxQn=80</code>）。</li><li><strong>服务端 <code>/api/cli/resolve</code></strong>：用 CLI 请求头自带的 B站 Cookie 解析（需含 SESSDATA），设 <code>skipCdnCheck: true</code>——实际媒体由本机浏览器经 CLI 拉取，无需服务端校验 CDN 可达性，避免远程网络差异造成错误降级。</li><li><strong>服务器解析锚定房主 Cookie</strong>：所有服务器侧解析（含观众 CLI 未连接时的 MP4 兜底）默认以影片所属房间<strong>房主的 B站 Cookie 身份</strong>执行，房主为大会员时会员内容全房间可拿完整地址；<code>useHostCookie: false</code> 可退回请求者身份。成员走本地 CLI 时不受影响，CLI 始终用观众自己的 Cookie。</li><li><strong>非会员档位保护</strong>：CLI 在线时查询会员状态，非会员选了会员档（qn &gt; 80）自动回落到 0（跟随账号默认档）。</li></ul><p>缓存：音频直链 TTL 2 小时，VIP 状态 5 分钟。</p><h2 id="前端接入点" tabindex="-1">前端接入点 <a class="header-anchor" href="#前端接入点" aria-label="Permalink to &quot;前端接入点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>行为</th></tr></thead><tbody><tr><td>音乐视频背景</td><td><code>useMusicVideoBackground</code>：CLI 在线 → CLI 高画质 DASH；否则服务器 720P MP4</td></tr><tr><td>音乐音源</td><td><code>resolveBiliAudio</code>：CLI 开启且在线 → CLI DASH 音轨；否则服务器代理 MP4</td></tr><tr><td>一起看影片</td><td>房间开关 <code>cliEnabled</code> 打开时可用；<code>hostCliEnabled</code> 经同步状态广播给观众（强制走 MP4 路径）</td></tr><tr><td>配置页入口</td><td><code>openCliSetup()</code> 打开 <code>http://127.0.0.1:9333/?server=&lt;api&gt;&amp;user=&lt;username&gt;</code>，CLI 读取参数预填，连接时 POST <code>/api/connect</code> 上报</td></tr></tbody></table><h2 id="断线重连与心跳" tabindex="-1">断线重连与心跳 <a class="header-anchor" href="#断线重连与心跳" aria-label="Permalink to &quot;断线重连与心跳&quot;">​</a></h2><ul><li><strong>CLI 侧</strong>由服务器主导 ping/pong：<code>lastActivityAt</code> 超过 <code>pingInterval + pingTimeout</code>（下限 45s）时强制重连；<code>reconnectLoop</code> 指数退避，base 2s / max 60s，叠加 ±25% 抖动。</li><li><strong>前端侧</strong>每 3s 轮询 <code>cli-list-agents</code>，同时监听 <code>cli-agent-available/unavailable/cli-agents</code> 实时刷新。</li></ul><h2 id="故障排查" tabindex="-1">故障排查 <a class="header-anchor" href="#故障排查" aria-label="Permalink to &quot;故障排查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>检查</th></tr></thead><tbody><tr><td>配置页无法连接</td><td>服务器地址可达性；CLI 是否仍运行（注册是内存态）；<code>-port</code> 是否被占用</td></tr><tr><td>代理列表为空</td><td>CLI 的 <code>user</code> 与网页登录用户名是否一致；是否完成 <code>cli-register</code></td></tr><tr><td>高画质仍失败</td><td>Cookie 是否有效；会员档是否被非会员保护回落；CLI 版本 ≥ 0.2.0</td></tr><tr><td>播放报 CORS</td><td>代理 URL host 是否规范为 127.0.0.1（旧版 CLI 会误报页面 host）</td></tr></tbody></table>`,19)])])}const k=o(s,[["render",d]]);export{g as __pageData,k as default};
